(()=>{const b=window.DriveQuizBank;if(!b)throw Error("Missing DriveQuizBank");b.questions.push(...[{"id":"rodrive-b-1051","batch":"22","category":"Categoria B","question":"Întoarcerea unui vehicul pe un drum presupune, înainte de efectuarea manevrei:","answers":["Semnalizarea și asigurarea din față, din spate și din lateral","Oprirea și semnalizarea intenției de a întoarce","Asigurarea și încadrarea pe banda de lângă axul drumului"],"correctIndices":[0],"correct":0,"explanation":"Întoarcerea vehiculului pe drumul public, fie prin viraj fie prin manevre înainte și înapoi, presupune, înainte de efectuarea manevrei, obligația de a semnaliza și de a vă asigura că din față din spate sau din lateral nu circulă în acel moment niciun vehicul, după care puteți efectua manevra.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1051.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1051.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1051; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1050 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/intoarcerea-unui-vehicul-pe-un-drum-presupune-inainte-de-efectuarea-manevrei","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1050","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1052","batch":"22","category":"Categoria B","question":"Unde vă este permisă staționarea pe partea stângă în direcția de mers?","answers":["Pe străzile cu sens unic","În nicio situație","Pe șoselele cu bandă laterală consolidată"],"correctIndices":[0],"correct":0,"explanation":"De regulă, vehiculele se opresc sau staționează pe dreapta drumului, aproape și paralel de margine. Excepție fac drumurile cu sens unic din localități, unde se poate opri sau staționa și pe stânga, dacă rămâne liberă cel puțin o bandă de circulație.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1052.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1052.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1052; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1051 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/unde-va-este-permisa-stationarea-pe-partea-stanga-in-directia-de-mers","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1051","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1053","batch":"22","category":"Categoria B","question":"Cum procedați când vă apropiați de o intersecție unde, în afara semaforului care are în funcțiune semnalul de culoare verde, întâlniți și indicatorul „Cedează trecerea“?","answers":["Respectați semnificația culorii semaforului","Respectați semnificația indicatorului rutier","Respectați semnificația semaforului și acordați prioritate de trecere vehiculelor care circulă pe drumul prioritar"],"correctIndices":[0],"correct":0,"explanation":"Conducătorul de vehicul este obligat să respecte semnificația semnalizării luminoase cu prioritate față de semnificația indicatoarelor de reglementare de prioritate. Semnificația indicatoarelor de reglementare de prioritate instalate lângă semafoare se va respecta când semafoarele nu funcționează sau funcționează pe culoarea galbenă intermitent. Prin urmare, în situația descrisă în întrebare, se va respecta culoarea verde a semaforului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1053.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1053.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1053; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1052 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-procedati-cand-va-apropiati-de-o-intersectie-unde-in-afara-semaforului-care-are-in-functiune-semnalul-de-culoare-verde-intalniti-si-indi","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1052","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1054","batch":"22","category":"Categoria B","question":"Ce mijloace de semnalizare pot fi folosite pentru evitarea unui pericol imediat, în zona de acțiune a indicatorului „Claxonarea interzisă”?","answers":["Niciun mijloc de semnalizare","Atât mijloacele de avertizare sonoră, cât și cele luminoase","Numai mijloacele de semnalizare luminoasă"],"correctIndices":[1],"correct":1,"explanation":"Avertizarea sonoră se folosește ori de câte ori este necesar, pentru evitarea unui pericol imediat. Chiar dacă pe drumul pe care circulați este instalat indicatorul „Claxonarea interzisă”, puteți folosi avertizarea sonoră pentru evitarea unui pericol imediat.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1054.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1054.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1054; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1053 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-mijloace-de-semnalizare-pot-fi-folosite-pentru-evitarea-unui-pericol-imediat-in-zona-de-actiune-a-indicatorului-claxonarea-interzisa","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1053","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1055","batch":"22","category":"Categoria B","question":"Autoturismul echipat cu o remorcă poate circula pe autostradă?","answers":["Nu","Da, dacă ansamblul respectiv poate depăși viteza de 50 km/h","Da, dacă ați obținut autorizație de la poliția rutieră"],"correctIndices":[1],"correct":1,"explanation":"Pe autostradă este permisă circulația vehiculelor echipate cu remorcă, dar cu condiția ca ansamblul respectiv să poată depăși viteză de 50 de km/h. De exemplu dacă un autoturism echipat cu remorcă poate circula cu o viteză mai mare de 50 de km/h, îi este permisă circulația pe autostradă. Trebuie să ținem cont de faptul că viteza maximă cu care se pot deplasa în afara localităților (implicit și pe autostradă) autovehiculele echipate cu remorcă este cu 10 km/h mai mică decât viteza maximă admisă. Astfel autoturismele, mai exact autovehiculele din categoria B, vor circula pe autostradă cu maxim 120 de km/h. Pentru a circula cu autoturismul echipat cu o remorcă pe autostradă NU este necesară o autorizație de la poliția rutieră. Autorizația specială de la varianta C de răspuns se obține de la administratorul drumului public și este necesară doar în anumite cazuri specifice, cum ar fi în cazul în care ansamblul respectiv de vehicule nu este permisă circulația pe autostradă în mod normal.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1055.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1055.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1055; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1054 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/autoturismul-echipat-cu-o-remorca-poate-circula-pe-autostrada","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1054","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1056","batch":"22","category":"Categoria B","question":"Ce reprezintă simbolurile EURO I, EURO II, EURO III și EURO IV?","answers":["Caracteristicile tehnice de proveniență a unor vehicule din uniunea europeană","Standardele de poluare din uniunea europeană","Încadrarea autovehiculelor în diferite norme de consum"],"correctIndices":[1],"correct":1,"explanation":"Simbolurile EURO I, EURO II, EURO III și EURO IV sunt simboluri ce țin de conduita ecologică la nivel european și reprezintă standardele de poluare din Uniunea Europeană. Cu cât numărul standardului de poluare este mai mare, cu atât nivelul de poluare este mai mic, astfel EURO III poluează mai mult decât EURO IV.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1056.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1056.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1056; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1055 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-reprezinta-simbolurile-euro-i-euro-ii-euro-iii-si-euro-iv","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1055","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1057","batch":"22","category":"Categoria B","question":"Într-un pansament, pe plagă, se aplică:","answers":["O compresă de vată sterilă","O compresă din tifon steril","O compresă oarecare"],"correctIndices":[1],"correct":1,"explanation":"Vata este foarte greu de îndepărtat din rană, de aceea între rană și vată trebuie pusă o compresă din tifon steril. Într-un pansament, primul lucru care se aplică direct pe plagă, este compresa din tifon steril. Executarea pansamentului: Este nevoie de o compresă sterilă. Dacă folosim o compresă oarecare există posibilitatea ca în organism să pătrundă microbi, bacterii, etc.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1057.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1057.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1057; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1056 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/intr-un-pansament-pe-plaga-se-aplica","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1056","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1058","batch":"22","category":"Categoria B","question":"Ce măsuri se recomandă atunci când urmează să străbateți o porțiune de drum public acoperită cu piatră cubică?","answers":["Să folosiți numai frâna de ajutor pentru a evita derapajul","Să reduceți din timp viteza, evitând bruscarea comenzilor","Să circulați cât mai aproape de axul drumului, pentru a evita lovirea acostamentului"],"correctIndices":[1],"correct":1,"explanation":"Frâna de ajutor, adică frâna de mână, nu se va folosi niciodată în timpul deplasării, aceasta va face ca autovehiculul să derapeze. Atunci când urmează să străbateți o porțiune de drum public acoperită cu piatră cubică, viteza trebuie redusă din timp și evitată bruscarea comenzilor autovehiculului, deoarece aderența este scăzută. Iar atunci când partea carosabilă este acoperită cu piatră cubică umedă, aveți obligația sa circulați cu o viteză care să nu depășească 30 km/h, în localități, sau 50 km/h în afara localităților. Nu se permite să circulați cât mai aproape de axul drumului, deoarece în timpul deplasării trebuie să se circule pe partea din dreapta a drumului public, în sensul de circulație, cât mai aproape de marginea părții carosabile.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1058.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1058.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1058; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1057 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-masuri-se-recomanda-atunci-cand-urmeaza-sa-strabateti-o-portiune-de-drum-public-acoperita-cu-piatra-cubica","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1057","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1059","batch":"22","category":"Categoria B","question":"Există vreo excepție de la regula depășirii pe partea stângă?","answers":["Nu","Da, în cazul autovehiculului care intenționează să vireze spre stânga, și în cazul tramvaiului","Da, numai în cazul în care depășirea se face pe o stradă semnalizată cu indicatorul „drum fără ieșire“"],"correctIndices":[1],"correct":1,"explanation":"Depășirea se efectuează,de regulă, pe partea stângă a vehiculului depășit. Însă legislația rutieră prevede că tramvaiele se depășesc prin partea dreaptă a acestora. De asemenea, deși regula generală a depășirii vehiculelor impune ca depășirea să se efectueze pe partea stângă, legislația rutieră prevede că vehiculul care a semnalizat și s-a încadrat corespunzător părăsirii sensului de mers spre stânga se depășește prin partea dreapta, cu condiția ca spațiul rămas la dispoziție să permită efectuarea acestei manevre. Trebuie să ținem cont că trebuie să se creeze spațiu suficient pentru a putea depăși aceste vehicule prin partea dreaptă, iar dacă nu există spațiu suficient, nu este permis să urcăm, chiar și parțial, pe trotuar.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1059.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1059.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1059; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1058 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/exista-vreo-exceptie-de-la-regula-depasirii-pe-partea-stanga","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1058","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1060","batch":"22","category":"Categoria B","question":"Care este ordinea de trecere prin intersecția prezentată?","answers":["Motocicleta, autoturismul, autocamionul","Autocamionul, autoturismul, motocicleta","Autoturismul, motocicleta, autocamionul"],"correctIndices":[2],"correct":2,"explanation":"Intersecția este dirijata cu indicatoare de reglementare de prioritate, autocamionul întâlnește indicatorul „Cedează trecerea” și trebuie să le acorde prioritate de trecere celorlalte două autovehicule. Autoturismul și motocicleta vin de pe drumuri cu prioritate și au prioritate de trecere, însă motocicleta schimbând direcția de mers către stânga trebuie să îi acorde autoturismului prioritate de dreapta, deoarece autoturismul îi vine din partea dreaptă. Ordinea de trecere este următoarea: primul va trece autoturismul, urmat de motocicletă, iar ultimul prin această intersecție va trece autocamionul.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1060.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1060.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1060; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Această intersecție este reglementată prin indicatoare triunghiulare cu margini roșii 'Cedează trecerea'. Motociclistul vine din stânga și vrea să vireze la stânga. Autoturismul vine din dreapta și vrea să meargă înainte. Autocamionul vine de sus și merge înainte, dar are indicatorul triunghiular cu margini roșii în față.","needsImageReview":true,"source":"RoDrive · ID 1059 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-este-ordinea-de-trecere-prin-intersectia-prezentata","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1059","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1088.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1061","batch":"22","category":"Categoria B","question":"Ce comportament este corect în situația prezentată, dacă vă aflați la volanul autoturismului verde?","answers":["Intrați cu atenție în intersecție și virați numai la stânga","Opriți și nu intrați în intersecție","Aveți voie să virați la dreapta"],"correctIndices":[1],"correct":1,"explanation":"Polițistul rutier execută un semnal cu brațele întinse orizontal, la adresarea acestui semnal trebuie să oprească participanții la trafic a căror direcție inițială de deplasare se intersectează cu brațele polițistului, mai exact vor opri cei care circulă din fața și din spatele polițistului. În această situație, conducând autoturismul verde, aveți obligația de a opri, deoarece direcția dumneavoastră inițială de deplasare se intersectează cu brațul polițistului. Autoturismul albastru își poate continua deplasarea.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1061.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1061.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1061; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un polițist care dirijează traficul într-o intersecție. Această intersecție este reglementată prin indicatoare triunghiulare cu margini roșii 'Cedează trecerea'. Motociclistul vine din stânga și merge înainte. Autoturismul vine din dreapta și virează la stânga. Autobuzul vine de sus și merge înainte, dar are indicatorul triunghiular cu margini roșii în față., în timp ce vehiculele din lateral pot circula. Autoturismul albastru se află pe lateral și vrea să meargă înainte. Autoturismul verde se află în fața polițistului și vrea să vireze la dreapta.","needsImageReview":true,"source":"RoDrive · ID 1060 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-comportament-este-corect-in-situatia-prezentata-daca-va-aflati-la-volanul-autoturismului-verde","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1060","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1089.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1062","batch":"22","category":"Categoria B","question":"Ce trebuie să aveți în vedere la urcarea într-un autoturism?","answers":["Să urcați numai pe partea dinspre trotuar","Să deschideți ușa numai dacă circulația permite acest lucru","Urcați fără grijă, deoarece vehiculele care circulă din spate sunt obligate să aștepte"],"correctIndices":[1],"correct":1,"explanation":"Nu se poate reglementa o astfel de obligație, șoferul autovehiculului nu ar mai avea pe unde să urce în autovehicul și ușa șoferului nu și-ar mai avea rostul. Dar, din punct de vedere al conduitei preventive, se recomandă ca părinții sau însoțitorii copiilor să se asigure că aceștia urcă și coboară din vehicule doar pe partea dinspre trotuar, atât timp cât acest lucru este posibil. La urcarea și la coborârea dintr-un autoturism, în special din cele oprite în apropierea parții carosabile, trebuie să aveți în vedere să deschideți portiera numai dacă circulația permite acest lucru, fără a perturba buna desfășurare a circulației rutiere. Vehiculele care circulă din spate nu au obligația să vă acorde prioritate, cu toate că aceștia o vor face, dar în caz de accident dvs. veți avea întreaga răspundere a accidentării. Însă trebuie să avem în vedere că cei care circulă din spate vă pot observa cu întârziere și nu vor avea timp să frâneze la timp, iar obligația de a se asigura îi revine celui care coboară din vehicule, așa cum este specificat la varianta B de răspuns.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1062.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1062.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1062; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1061 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-trebuie-sa-aveti-in-vedere-la-urcarea-intr-un-autoturism","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1061","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1063","batch":"22","category":"Categoria B","question":"Sunteți corespunzător încadrat pentru a folosi prima ieșire de pe autostradă?","answers":["Da, deoarece circulați pe banda din dreapta","Nu, deoarece veți călca banda continuă","Nu, pentru că circulați pe banda de urgență"],"correctIndices":[2],"correct":2,"explanation":"Pe autostradă este interzisă circulația, oprirea sau staționarea pe banda de urgență, cu excepția cazurilor justificate. Prin urmare, în situația dată, dorind să părăsiți autostrada, vă este interzis să circulați pe banda de urgență, trebuie să vă încadrați pe prima bandă a autostrăzii iar în apropierea nodului rutier care vă permite ieșirea de pe autostradă vă veți angaja pe banda de decelerare, adică pe banda de reducere a vitezei și de ieșire de pe autostradă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1063.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1063.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1063; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea arată un șofer pe banda de urgență de pe o autostradă.","needsImageReview":true,"source":"RoDrive · ID 1062 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/sunteti-corespunzator-incadrat-pentru-a-folosi-prima-iesire-de-pe-autostrada","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1062","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1091.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1064","batch":"22","category":"Categoria B","question":"Conducătorul autocamionului poate pătrunde în intersecție?","answers":["Da","Nu, în intersecție vor pătrunde tramvaiul și autoturismul","Nu, indicatorul „cedează trecerea“ îl obligă să acorde prioritate celorlalte vehicule"],"correctIndices":[0],"correct":0,"explanation":"Polițistul rutier execută un semnal cu brațele întinse orizontal, acest semnal semnifică oprire pentru toți participanții la trafic a căror direcție inițială de deplasare se intersectează cu brațele acestuia, mai exact pentru cei care circulă din fața și din spatele polițistului. În situația dată, direcția inițială de deplasare a tramvaiului și a autoturismului se intersectează cu brațele polițistului, fiind obligați să oprească, autocamionul putând să își continue deplasarea, deoarece direcția sa inițială de deplasare nu se intersectează cu brațele polițistului. Prin urmare, la semnalul adresat de polițist își poate continua deplasarea doar autocamionul.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1064.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1064.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1064; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție dirijată de un polițist și semnalizată cu indicatoare 'Cedează trecerea'. Brațele întinse lateral indică oprirea pentru vehiculele care vin din fața și din spatele polițistului. Tramvaiul și autoturismul se află înaintea și în spatele polițistului. Autocamionul se află în stânga polițistului și intenționează să vireze la stânga.","needsImageReview":true,"source":"RoDrive · ID 1063 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/conducatorul-autocamionului-poate-patrunde-in-intersectie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1063","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1092.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1065","batch":"22","category":"Categoria B","question":"Criteriul de alegere a benzinei pentru motoarele cu aprindere prin scânteie îl constituie:","answers":["Culoarea și consistența","Cifra octanică (co)","Cifra cetanică (cc)"],"correctIndices":[1],"correct":1,"explanation":"Culoarea benzinei nu reprezintă un criteriu de alegere a benzinei, însă consistența acesteia poate fi un criteriu. Criteriul de alegere a benzinei pentru motoarele cu aprindere prin scânteie îl constituiecifra octanică (CO). Cifra octanică (CO) reprezintărezistența unui combustibil la detonațieși poate fi între0 și 100. În România benzinele cele mai des întâlnite sunt cu cifra octanică de 95 sau 98. Benzina cu CO 98, fiind mai rezistenta la detonație, este recomandată a se utiliza la motoarele care au raport de comprimare mărit. Cifra cetanică (CC) caracterizează ușurința la autoaprindere a combustibilului pentru motoare cu aprindere prin comprimare și se definește prin compararea comportării combustibilului cu cea a unui amestec etalon, format din hidrocarburi cu calități de autoaprindere opuse. Acestanu esteun criteriu de alegere a benzinei pentru motoarele cu aprindere prin scânteie.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1065.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1065.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1065; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1064 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/criteriul-de-alegere-a-benzinei-pentru-motoarele-cu-aprindere-prin-scanteie-il-constituie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1064","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1066","batch":"22","category":"Categoria B","question":"Ce autovehicule pot pătrunde în intersecție?","answers":["Troleibuzul și motocicleta","Motocicleta și autocamionul","Troleibuzul"],"correctIndices":[1],"correct":1,"explanation":"Polițistul rutier execută un semnal cu brațele întinse orizontal, la adresarea acestui semnal trebuie să oprească participanții la trafic a căror direcție inițială de deplasare se intersectează cu brațele polițistului, mai exact vor opri cei care circulă din fața și din spatele polițistului. În această situație, din fața și din spatele polițistului circulă troleibuzul și autoturismul, aceștia au obligația să oprească deoarece direcțiile lor inițiale de deplasare se intersectează cu brațele întinse ale polițistului. Prin urmare, în această intersecție pot pătrunde motocicleta și autocamionul.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1066.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1066.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1066; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea arată o intersecție dirijată de un polițist. Brațele întinse lateral indică oprirea pentru vehiculele care vin din fața și din spatele polițistului, iar cele din lateral pot circula. Autoturismul roșu și motociclistul se află în spatele și în fața polițistului. Autocamionul și motocicleta se află la stânga, respectiv la dreapta polițistului","needsImageReview":true,"source":"RoDrive · ID 1065 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-autovehicule-pot-patrunde-in-intersectie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1065","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1095.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1067","batch":"22","category":"Categoria B","question":"Semnalul de culoare galbenă al semaforului:","answers":["Permite intrarea în intersecție, dacă urmează după lumina verde","Permite schimbarea direcției de mers către dreapta","Interzice intrarea în intersecție, dacă vehiculul poate fi oprit în condiții de siguranță"],"correctIndices":[2],"correct":2,"explanation":"În situația în care semnalul verde se schimbă cu cel galben, acest semnal anunță apariția semnalului de culoare roșie și obligă conducătorii de vehicule la oprire, iar dacă vehiculul se află prea aproape de intersecție la apariția semnalului galben și nu poate opri în condiții de siguranță, nu are obligația de a opri. Vehiculul trebuie oprit înaintea marcajului pentru oprire sau, după caz, pentru trecerea pietonilor, iar în lipsa acestuia, în dreptul semaforului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1067.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1067.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1067; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1066 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/semnalul-de-culoare-galbena-al-semaforului","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1066","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1068","batch":"22","category":"Categoria B","question":"Ce obligație are conducătorul auto când a accidentat un pieton care a traversat strada neregulamentar?","answers":["Transportă victima la cea mai apropiată unitate sanitară, dacă nu este posibilă transportarea cu alte mijloace, și se reîntoarce imediat la locul accidentului","Rămâne la locul accidentului până la sosirea organelor de anchetă, reținând numele, prenumele și adresele martorilor","Se prezintă la cel mai apropiat post de poliție"],"correctIndices":[0],"correct":0,"explanation":"Conducătorul de vehicul care a accidentat un pieton ce a traversat strada, indiferent dacă pietonul traversa regulamentar sau nu, are obligațiasă anunțe poliția,să nu modifice urmele accidentuluișisă nu părăsească locul faptei. În acest caz este interzisă părăsirea locului faptei fără încuviințarea poliției sau a procurorului care efectuează cercetarea. Nerespectarea interdicției de a părăsi locul fapteieste considerată infracțiuneși se pedepsește cuînchisoarea de la 2 la 7 ani. Cu toate acestea,NUconstituie infracțiunesituația în care,în lipsa altor mijloace de transport, conducătorul vehiculului implicat în accident transportă el însuși persoana rănită la cel mai apropiat spital,acesta având obligațiade a declara datele personale de identitate și numărul de înmatriculare sau înregistrare a vehiculului condus, date ce se vor consemna într-un registru special, și de a se reîntoarce imediat la locul accidentului. Reținerea numelor și adresele martorilor nu intră în obligațiile pe care legislația rutieră le impune conducătorilor de vehicule ce au fost implicați în accidente de circulație. Pentru că accidentul a fost soldat cu victime, vă este interzisă părăsirea locului faptei fără încuviințarea poliției sau a procurorului care efectuează cercetarea, aceasta fiind considerată infracțiune, excepție făcând situația în care se transportă victima la cel mai apropiat spital, excepție detaliată la explicația variantei A de răspuns. Codul penal prevede că, în cazul implicării într-un astfel de accident, părăsirea locului accidentului nu constituie infracțiune nici atunci cândvictima","imageUrl":"/nivel-1/quiz-images/rodrive-all/1068.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1068.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1068; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1067 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatie-are-conducatorul-auto-cand-a-accidentat-un-pieton-care-a-traversat-strada-neregulamentar","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1067","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1069","batch":"22","category":"Categoria B","question":"Care dintre autovehicule pot traversa intersecția din imagine?","answers":["Niciunul","Autocamionul și autobuzul","Autoturismul galben și autoturismul roșu"],"correctIndices":[0],"correct":0,"explanation":"Intersecția din imagine este dirijată cu semnale luminoase. Autoturismul roșu nu își poate continua deplasarea pe direcția dorită, deoarece întâlnește semnalul roșu al semaforului. De asemenea autobuzul și autocamionul dorind să circule pe direcția înainte trebuie să respecte semnificația semnalului semaforului din partea dreaptă, semnalul acestui semafor fiind roșu, nici aceștia nu își pot continua deplasarea pe direcția dorită. Autoturismul galben dorește să circule pe direcția înainte dar s-a încadrat neregulamentar pe banda pentru virajul către stânga, semaforul care are în funcțiune semnalul de culoare verde permite trecerea vehiculelor care doresc să vireze către stânga. Astfel autoturismul galben nu își poate continua deplasarea pe direcția dorită. Însă autoturismul galben trebuie să elibereze banda de circulație pe care s-a încadrat neregulamentar pentru a permite trecerea vehiculelor care virează către stânga la culoarea verde a semaforului, acesta fiind obligat să vireze către stânga deoarece pe direcția înainte circulația este interzisă. Prin urmare, în această intersecție niciun autovehicul nu își poate continua deplasarea pe direcția dorită (direcția dorită fiind cea indicată de săgețile colorate din imaginea întrebării).","imageUrl":"/nivel-1/quiz-images/rodrive-all/1069.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1069.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1069; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție semaforizată cu mai multe benzi de circulație. Vehiculul roșu(vine de jos) vrea să vireze la dreapta, iar celelalte vehicule inteționează să se deplaseze înainte(vin din stânga), conform semnalizării luminoase. Vehiculul roșu are în dreptul său un semafor roșu. Celelalte trei vehicule , adică autocamionul, autobuzul și autoturismul galben au în dreptul lor un semafor verde pentru direcția stânga și un semafor roșu pentru direcția înainte sau la dreapta. Autoturismul galben este încadrat pe banda care îl obligă să vireze la dreapta, deși dorința sa este să meargă înainte.","needsImageReview":true,"source":"RoDrive · ID 1068 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-dintre-autovehicule-pot-traversa-intersectia-din-imagine","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1068","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1098.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1070","batch":"22","category":"Categoria B","question":"Aveți obligația de a opri imediat vehiculul la semnalele adresate de:","answers":["Îndrumătorii de circulație ai ministerului apărării","Un conducător auto rămas în pană, pentru a-l remorca","Polițiștii comunitari"],"correctIndices":[0],"correct":0,"explanation":"Pe lângă obligația de a opri la semnalele polițistului rutier, participanții la trafic sunt obligați să oprească imediat și la semnalele adresate în acest sens de către îndrumătorii de circulație ai Ministerului Apărării. Aceștia din urmă pot efectua, pe lângă semnalele de oprire, și următoarele semnale: balansarea brațului în plan vertical, cu palma mâinii orientată către sol sau cu un mijloc de semnalizare, care semnifică reducerea vitezei, precum și rotirea vioaie a brațului, care semnifică mărirea vitezei de deplasare a vehiculelor, inclusiv grăbirea traversării drumului de către pietoni. Nerespectarea acestor semnale se sancționează cu amendă prevăzută în clasa a II-a de sancțiuni. Legislația rutieră nu prevede obligația de a opri la semnalele adresate de către un conducător auto rămas în pană, pentru a-l remorca. Legislația rutieră nu prevede obligația de a opri la semnalele adresate de polițiștii comunitari. Din anul 2010 termenul „poliție comunitară” nu mai există în actele normative în vigoare. În acest moment termenul care se găsește în actele normative în vigoare este „poliție locală”.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1070.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1070.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1070; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1069 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/aveti-obligatia-de-a-opri-imediat-vehiculul-la-semnalele-adresate-de","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1069","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1071","batch":"22","category":"Categoria B","question":"În prima intersecție:","answers":["Veți ceda trecerea vehiculelor care circulă din dreapta","Aveți prioritate de trecere","Veți ceda trecerea vehiculelor care circulă din stânga"],"correctIndices":[1],"correct":1,"explanation":"În situația dată întâlniți indicatorul “Intersecție cu un drum fără prioritate”, acest indicator vă avertizează că urmează o intersecție cu un drum fără prioritate, intersecție în care veți avea prioritate de trecere. Vehiculele care vin de pe drumul cu care vă intersectați au obligația să vă acorde prioritate de trecere. Indicatoarele care dirijează acest tip de intersecție sunt indicatoarele aflate pe drumurile laterale: ''Oprire'' și/sau ''Cedează trecerea''.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1071.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1071.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1071; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție semnalizată cu indicatorul triunghiular roșu cu săgeată îngroșată în sus intersectată de o linie orizontală neagră ce reprezintă 'Intersecție cu un drum fără prioritate'.","needsImageReview":true,"source":"RoDrive · ID 1070 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-prima-intersectie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1070","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1100.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1072","batch":"22","category":"Categoria B","question":"Ce obligații aveți la semnalele agenților căilor ferate, plasați la trecerea la nivel cu o cale ferată?","answers":["Nicio obligație, deoarece agenții căilor ferate dirijează garniturile de tren","Să vă conformați semnificației semnalelor acestora","Să reduceţi viteza, să vă asiguraţi, iar, dacă trenul nu este în mişcare, puteţi să continuaţi traversarea căii ferate cu atenţie"],"correctIndices":[1],"correct":1,"explanation":"Conducătorii de vehicule sunt obligați să se conformeze semnificației semnalelor agenților căilor ferate, plasați la trecerea la nivel cu o cale ferată. Agenții de cale ferată se pot întâlni atât la trecerile la nivel cu calea ferată industrială cât și la trecere la nivel cu calea ferată curentă. De știut că la trecerea la nivel cu calea ferată industrială, atunci când pe aceasta urmează să se deplaseze un vehicul feroviar, circulația rutieră va fi dirijată obligatoriu de un agent de cale ferată, iar la trecerea la nivel cu calea ferată curentă se poate întâlni un agent de cale ferată care să dirijeze circulația rutieră, dar prezența acestuia nu este obligatorie.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1072.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1072.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1072; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1071 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatii-aveti-la-semnalele-agentilor-cailor-ferate-plasati-la-trecerea-la-nivel-cu-o-cale-ferata","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1071","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1073","batch":"22","category":"Categoria B","question":"Conducătorul autoturismului roșu s-a angajat corect în depășirea autocamionului?","answers":["Nu, deoarece nu s-a asigurat și nu a semnalizat intenția de a depăși","Da, deoarece din sens opus nu circulă niciun vehicul","Nu, deoarece încalcă semnificația indicatorului"],"correctIndices":[0],"correct":0,"explanation":"În situația dată conducătorul autoturismului roșu nu s-a angajat corect în depășirea autocamionului. Legislația rutieră impune anumite obligații pentru conducătorul vehiculului care efectuează manevra de depășire, printre care se numără și obligația de a se asigura că acela care îl urmează sau îl precedănu a semnalizat intenția începerii unei manevre similare, precum și obligația de a semnaliza intenția de efectuare a manevrei. În acest caz autoturismul roșu nu a respectat aceste obligații și a început efectuarea manevrei de depășire chiar dacă autovehiculul albastru din spateera deja angajat regulamentar în depășire. Mai mult de atât, conducătorul autoturismului roșu nu a respectat nici obligația de a semnaliza intenția de efectuare a manevrei de depășire. Indicatorul din imagine nu se adresează conducătorilor de autovehicule din categoria B. Acest indicator interzice conducătorilor deautovehicule de transport marfăsă efectueze manevra de depășire a autovehiculelor, excepție făcând motocicletele fără ataș și mopedele, care pot fi depășite. Prin urmare, în această situație autoturismul roșu nu execută regulamentar manevra de depășire.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1073.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1073.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1073; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea arată o situație de trafic în care atât autoturismul roșu cât și autoturismul albastru din spatele său, intenționează să depășească camionul din fața lor. Autoturismul albastru semnalizează intenția de a depăși și se află mai mult pe contrasens decât autoturismul roșu. Autoturismul roșu nu semnalizează intenția de a depăși dar tot vrea să efectueze această manevră. Indicatorul circular cu margini roșii și un camion roșu în stânga și o mașină neagră în stânga, interzice camioanelor să depășească.","needsImageReview":true,"source":"RoDrive · ID 1072 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/conducatorul-autoturismului-rosu-s-a-angajat-corect-in-depasirea-autocamionului","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1072","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1102.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1074","batch":"22","category":"Categoria B","question":"Ce obligații aveți atunci când urmează să părăsiți autostrada?","answers":["Să reduceți viteza începând cu 300 m înainte de ieșirea de pe autostradă, în dreptul panoului care marchează această distanță","Să circulați pe prima bandă cu o viteză de maximum 60 km/oră","Să semnalizați din timp și să vă angajați pe banda de ieșire (decelerare)"],"correctIndices":[2],"correct":2,"explanation":"Atunci când doriți să părăsiți autostrada, trebuie să semnalizați din timp manevra și să vă angajați pe banda de decelerare, după care reduceți viteza de deplasare. Banda de decelerare, cunoscută și sub denumirea de bandă de ieșire, este concepută special pentru a permite reducerea vitezei de deplasare fără a perturba fluxul de trafic de pe autostradă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1074.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1074.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1074; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1073 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatii-aveti-atunci-cand-urmeaza-sa-parasiti-autostrada","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1073","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1075","batch":"22","category":"Categoria B","question":"Schimbarea uleiului și a elementului filtrant se face:","answers":["Conform periodicității stabilite de constructor","Din 5 în 5 ani","Din 3 în 3 ani"],"correctIndices":[0],"correct":0,"explanation":"Sistemul de ungere este esențial petru buna funcționare a motorului, de aceea se recomandă verificarea periodică a uleiului din baie cu ajutorul jojei de ulei. Nivelul corect al uleiului în baie trebuie să fie între reperele minim și maxim însemnate pe joja de ulei. Iar schimbarea uleiului și a elementului filtrant (filtrul de ulei) se face la un anumit număr de km parcurși, specificat de constructorul autovehiculului, sau conform perioadei de valabilitate a uleiului. Uleiul de motor își pierde proprietățile datorită uzurii de folosire dar și prin uzura de timp. Chiar dacă nu se efectuează numărul de kilometri specificați în manualul de service dar se depășește intervalul de timp (uleiul expiră), acesta trebuie înlocuit. Odată cu înlocuirea uleiului se va înlocui și filtrul de ulei.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1075.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1075.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1075; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1074 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/schimbarea-uleiului-si-a-elementului-filtrant-se-face","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1074","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1076","batch":"22","category":"Categoria B","question":"Ce semnifică semnalul roșu al semaforului, care funcționează concomitent cu cel galben?","answers":["Semaforul este în regim de avarie","Trecerea unei coloane de vehicule","Oprire"],"correctIndices":[2],"correct":2,"explanation":"Semnalul de culoare roșie al semaforului interzice trecerea. Însă atunci când semnalul de culoare roșie funcționează concomitent cu cel de culoare galbenă, acesta anunță apariția semnalului de culoare verde. Prin urmare, semnalul roșu al semaforului, care funcționează concomitent cu cel galben, semnifică oprire.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1076.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1076.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1076; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o trecere de pietoni semnalizată cu un semafor cu lumina roșie și lumina galbenă aprinse.","needsImageReview":true,"source":"RoDrive · ID 1075 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-semnifica-semnalul-rosu-al-semaforului-care-functioneaza-concomitent-cu-cel-galben","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1075","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1104.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1077","batch":"22","category":"Categoria B","question":"De ce este necesar să măriți distanța față de autovehiculul care circulă în fața dvs., atunci când circulați pe un carosabil umed?","answers":["Deoarece aderența anvelopelor pe partea carosabilă scade, iar spațiul de frânare crește","Deoarece nu puteți sesiza prompt aprinderea lămpilor de stop ale autovehiculului din față, atunci când acesta frânează","Deoarece roțile autovehiculului din față aruncă spre dvs. criblură"],"correctIndices":[0],"correct":0,"explanation":"În toate situațiile în care partea carosabilă devine alunecoasă, distanța de siguranță față de vehiculul din față trebuie să fie considerabil mai mare, deoarece în aceste situații aderența anvelopelor pe partea carosabilă scadeiar spațiul de frânare crește semnificativ. Circulația pe un carosabil umed nu are legătură cu starea de vigilență sau cu întârzierea reflexelor șoferului. Criblura este piatră dură, sfărâmată mărunt și sortată după dimensiuni standardizate, folosită ca îmbrăcăminte rutieră. Această criblură poate fi aruncată doar de pe porțiunile de drum pe care aceasta există, dar în situația din întrebare nu este specificat acest lucru.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1077.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1077.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1077; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1076 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/de-ce-este-necesar-sa-mariti-distanta-fata-de-autovehiculul-care-circula-in-fata-dvs-atunci-cand-circulati-pe-un-carosabil-umed","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1076","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1078","batch":"22","category":"Categoria B","question":"Cum veți proceda corect în intersecția dată?","answers":["Respectați indicațiile semnalului luminos, dacă toate semafoarele au aceeași culoare, în același timp","Respectați regulile generale de circulație, dacă semafoarele nu au aceeași culoare","Respectați semnificația semnalului luminos pentru virajul la stânga"],"correctIndices":[2],"correct":2,"explanation":"În această situație întâlniți două semafoare cu semnale de culori diferite, însă sub fiecare semafor se găsește câte un panou adițional, în acest caz, semnalele semafoarelor se vor respecta de către cei a căror direcție de deplasare se regăsește pe aceste panouri adiționale. Dvs. v-ați încadrat pe banda pentru virajul către stânga, deci doriți să virați către stânga și va trebui să respectați semnificația semnalului semaforului pentru virajul către stânga. Semnalul acestui semafor fiind de culoare roșie, trebuie să opriți și să așteptați apariția semnalului de culoare verde.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1078.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1078.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1078; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție semaforizată cu indicatoare 'Drum cu prioritate' și săgeți direcționale. Semaforul verde permite deplasarea înainte, iar semaforul roșu interzice deplasarea la stânga. Șoferul se află pe banda cu o săgeată spre stânga, ce îl obligă să vireze la stânga.","needsImageReview":true,"source":"RoDrive · ID 1077 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-veti-proceda-corect-in-intersectia-data","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1077","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1107.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1079","batch":"22","category":"Categoria B","question":"În ce ordine vor trece prin intersecție autoturismele la culoarea galbenă intermitentă a semaforului?","answers":["Roșu, verde, albastru","Roșu, albastru, verde","Verde, albastru, roșu"],"correctIndices":[2],"correct":2,"explanation":"În intersecția din imagine semafoarele funcționează pe culoarea galbenă intermitentă, situație în care se va respecta semnificația indicatoarelor de reglementare de prioritate. Autoturismul roșu întâlnește indicatorul “Cedează trecerea” și trebuie să acorde prioritate de trecere celorlalte autoturisme. Deci autoturismul albastru și cel verde circulă pe drumul cu prioritate, între acestea se va aplica regula priorității de dreapta. Autoturismul albastru trebuie să îi acorde autoturismului verde prioritate deoarece virând către stânga, autoturismul verde îi vine din partea dreaptă. Ordinea de trecere este următoarea: primul va trece autoturismul verde, urmat de autoturismul albastru, iar ultimul prin această intersecție va trece autoturismul roșu.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1079.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1079.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1079; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Această intersecție este reglementată prin indicatoare 'Cedează trecerea' și semafoare. Semafoarele au lumina galbenă intermitentă, pe toate direcțiile. Autoturismul roșu circulă înainte(vine de sus), autoturismul albastru virează la stânga(vine din stânga), iar autoturismul verde merge înainte(vine din dreapta). Autoturismul roșu, pe lânga un semafor menționat anterior, are și indicatorul triunghiular, cu margini roșii, de cedare a trecerii.","needsImageReview":true,"source":"RoDrive · ID 1078 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-ce-ordine-vor-trece-prin-intersectie-autoturismele-la-culoarea-galbena-intermitenta-a-semaforului","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1078","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1108.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1080","batch":"22","category":"Categoria B","question":"Ce trebuie să verificați la un autoturism cu rulotă, înainte de a porni la drum?","answers":["Dacă sistemul de alimentare cu apă al rulotei funcționează","Dacă vizibilitatea în spate, prin oglinzile retrovizoare, este asigurată","Dacă persoanele transportate în rulotă poartă centura de siguranță"],"correctIndices":[1],"correct":1,"explanation":"Nu toate rulotele au sistem de alimentare cu apă, dar și dacă toate ar avea, funcționarea lui nu afectează în niciun fel deplasarea în siguranță a ansamblului de vehicule, acesta ține doar de confortul celor care vor locui în rulotă. Atunci când conduceți un autoturism simplu, trebuie să verificați funcționarea sistemului de lumini, sistemului de semnalizare și a instalației de climatizare. Dar atunci când intenționați să vă deplasați cu un autoturism echipat cu rulotă, trebuie să vă asigurați și că vizibilitatea prin oglinzile retrovizoare nu este împiedicată de rulotă. Vizibilitatea prin oglinzile retrovizoare se poate împiedica din cauza lățimii rulotei. Legislația RAR ne spune că rulota este remorca care poate servi drept locuință. Prin urmare, rulota este o remorca, iar în remorcă nu este permis să fie transportate persoane, cu excepția cazului în care aceasta este special destinată pentru transportul persoanelor.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1080.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1080.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1080; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1079 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-trebuie-sa-verificati-la-un-autoturism-cu-rulota-inainte-de-a-porni-la-drum","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1079","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1081","batch":"22","category":"Categoria B","question":"Fenomenul de acvaplanare generează următoarele pericole:","answers":["Stropirea cu apă a parbrizului","Stropirea cu apă a clădirilor și a pietonilor","Pierderea controlului asupra direcției"],"correctIndices":[2],"correct":2,"explanation":"Fenomenul de acvaplanare generează pierderea controlului asupra direcției autovehiculului. Acvaplanarea, se produce atunci când pe carosabil se află un strat de apă care împiedică anvelopa să aibă contact cu asfaltul. În aceste condiții, controlul autovehiculului devine aproape imposibil. În general, acvaplanarea apare când două situații se întrunesc: carosabil acoperit cu apă pe porțiuni mari și viteza mare de deplasare a autovehiculului. Acvaplanarea poate fi evitată dacă pneurile nu sunt uzate, iar viteza este redusă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1081.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1081.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1081; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1080 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/fenomenul-de-acvaplanare-genereaza-urmatoarele-pericole","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1080","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1082","batch":"22","category":"Categoria B","question":"Vă apropiați de un drum forestier, ce intră în șosea din partea dreaptă și de pe care iese un alt vehicul. Cine trebuie să aștepte?","answers":["Dvs., pentru că acordați prioritate de dreapta","Vehiculul care iese de pe drumul forestier","Vehiculul care circulă cu viteză mai mare"],"correctIndices":[1],"correct":1,"explanation":"Drumurile forestiere sunt drumuri private, iar conducătorii de vehicule care pătrund pe drumul public venind de pe o proprietate alăturată acestuia trebuie să acorde prioritate celor care circulă pe drumul public. Prin urmare, atunci când drumul public pe care circulați se intersectează cu un drum forestier de pe care iese un alt vehicul, vă puteți continua deplasarea deoarece vehiculul care iese de pe drumul forestier are obligația să vă acorde prioritate de trecere.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1082.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1082.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1082; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1081 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/va-apropiati-de-un-drum-forestier-ce-intra-in-sosea-din-partea-dreapta-si-de-pe-care-iese-un-alt-vehicul-cine-trebuie-sa-astepte","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1081","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1083","batch":"22","category":"Categoria B","question":"Care autoturisme s-au încadrat corect pentru a traversa intersecția prezentată?","answers":["Toate","Autoturismul verde și cel roşu","Autoturismul albastru și cel galben"],"correctIndices":[0],"correct":0,"explanation":"În intersecția din imagine circulația se desfășoară în sens giratoriu. Legislația rutieră nu stabilește reguli speciale de selectare a benzilor pentru intersecțiile cu sens giratoriu, caz în care se vor respecta regulile generale de selectare a benzilor în intersecții. Prin urmare, toate autoturismele s-au încadrat corespunzător pentru a traversa intersecția prezentată. Dar acestea trebuie să respecte regulile cu privire la semnalizarea schimbării direcției de mers, acordarea priorității la schimbarea benzii de circulație și acordarea priorității la intrarea în sensul giratoriu.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1083.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1083.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1083; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un sens giratoriu cu mai multe benzi, fiecare având direcții marcate. Vehiculul galben circulă pe banda interioară pentru a ieși la ultima sau penultima ieșire, iar vehiculul roșu virează la dreapta de pe banda exterioară. Autoturismul verde virează la dreapta, tot de pe banda exterioară, cu o ieșire înaintea celui roșu, iar autoturismul albastru virează la dreapta, pe banda exterioară, cu o ieșire după cel roșu. Toate vehiculele sunt în sensul giratoriu și nu se intersectează.","needsImageReview":true,"source":"RoDrive · ID 1082 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-autoturisme-s-au-incadrat-corect-pentru-a-traversa-intersectia-prezentata","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1082","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1112.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1084","batch":"22","category":"Categoria B","question":"Ce obligații aveți dacă luminile roșii se aprind și se sting alternativ?","answers":["Reduceți viteza și, după ce vă asigurați, vă continuați deplasarea","Reduceți viteza și opriți numai în cazul în care se apropie un tren","Opriți fără a depăși indicatorul"],"correctIndices":[2],"correct":2,"explanation":"În situatia dată întâlniți o trecere la nivel cu o cale ferată curentă fără bariere, prevăzută cu semnalizare automată, iar luminile roșii se aprind și se sting alternativ. În acest caz vă este interzisă traversarea și aveți obligația să opriți fără a depăși indicatorul. Așteptați stingerea luminilor de culoare roșie și a semnalului sonor, iar după apariția semnalului intermitent cu lumină de culoare albă cu cadență lentă vă puteți continua deplasarea.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1084.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1084.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1084; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o trecere la nivel cu calea ferată semnalizată cu 'Crucea Sfântului Andrei' și lumini roșii intermitente.","needsImageReview":true,"source":"RoDrive · ID 1083 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatii-aveti-daca-luminile-rosii-se-aprind-si-se-sting-alternativ","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1083","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1113.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1085","batch":"22","category":"Categoria B","question":"Care este valoarea alcoolemiei în sânge peste care se aplică pedeapsa penală pentru un conducător aflat la volan?","answers":["0,5 g/l","0,8 g/l","1 g/l"],"correctIndices":[1],"correct":1,"explanation":"Conducerea pe drumurile publicea unui vehicul pentru care legea prevede obligativitatea deținerii permisului de conducerede către o persoană care are o îmbibație alcoolicădepeste 0,80 g/lalcool pur în sângeconstituieinfracțiuneși se pedepsește penal, cu închisoare de la unu la 5 ani sau cu amendă. În schimb, în cazul unei îmbibațiimai mici sau egale cusub 0,8 g/lalcool pur în sânge, aceasta constituiecontravențieși se sancționează cu amenda prevăzută în clasa a-IV-a de sancțiuni și cu suspendarea exercitării dreptului de a conduce pentru o perioada de 90 de zile. Trebuie să reținem că o concentrațiemai mică sau egală cu0,8 g/lalcool pur însângeconstituiecontravențieși se sancționează contravențional. Iar o concentrațiemai mare de0,8 g/lalcool pur însângeconstituieinfracțiunesi se pedepsește penal.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1085.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1085.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1085; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1084 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-este-valoarea-alcoolemiei-in-sange-peste-care-se-aplica-pedeapsa-penala-pentru-un-conducator-aflat-la-volan","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1084","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1086","batch":"22","category":"Categoria B","question":"Cum veți proceda la întâlnirea indicatorului alăturat?","answers":["Circulați cu atenție, deoarece urmează o intersecție cu cedarea trecerii la 300 m","Reduceți viteza, vă asigurați și cedați trecerea tuturor vehiculelor care circulă pe o distanță de 300 m","Circulați cu atenție, pentru a putea opri în condiții de siguranță, în maximum 300 m"],"correctIndices":[0],"correct":0,"explanation":"Indicatorul “Cedează trecerea”, însoțit de panoul adițional „Distanța între indicator și începutul locului periculos” care indică “300 m”, vă informează că peste 300 de metri urmează o intersecție în care veți întâlni indicatorul “Cedează trecerea”. Prin urmare, la întâlnirea acestor indicatoare trebuie să circulați cu atenție deoarece urmează o intersecție cu cedarea trecerii la 300 de metri.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1086.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1086.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1086; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Indicatorul triunghiular cu margini roșii, 'Cedează trecerea' este însoțit de un panou adițional care indică distanța de 300 m până la intersecția unde se aplică efectul indicatorului.","needsImageReview":true,"source":"RoDrive · ID 1085 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-veti-proceda-la-intalnirea-indicatorului-alaturat","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1085","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1115.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1087","batch":"22","category":"Categoria B","question":"Care este rolul uleiului pentru motor?","answers":["Asigură demontarea mai ușoară a pieselor motorului","Reduce uzura motorului, prin crearea unui film rezistent de lubrifiant între suprafețele pieselor aflate în mișcare","Protejează motorul față de pătrunderea amestecului carburant în baia de ulei"],"correctIndices":[1],"correct":1,"explanation":"Uleiul pentru motor este parte a sistemului de lubrifiere (sistem de ungere) și are rolul de a reduce uzura motorului, prin crearea unui film rezistent de lubrifiant între suprafețele pieselor aflate în mișcare. Sistemul de ungere este esențial petru buna funcționare a motorului, de aceea se recomandă verificarea periodică a uleiului din baie cu ajutorul jojei de ulei. Nivelul corect al uleiului în baie trebuie să fie între reperele minim și maxim însemnate pe joja de ulei. Iar schimbarea uleiului și a elementului filtrant se face la un anumit număr de km parcurși, specificat de constructorul autovehiculului, sau conform perioadei de valabilitate a uleiului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1087.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1087.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1087; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1086 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-este-rolul-uleiului-pentru-motor","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1086","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1088","batch":"22","category":"Categoria B","question":"Cum veți proceda pentru a traversa intersecția dacă întâlniți indicatorul „Cedează trecerea“?","answers":["Reduceți viteza numai dacă se apropie vreun autovehicul","Reduceți viteza, vă asigurați, iar dacă pe drumul transversal circulă în acel moment alte vehicule, opriți pentru a le acorda prioritate de trecere","Reduceți viteza și vă asigurați, pentru a fi în măsură să acordați prioritate de trecere vehiculelor care circulă din partea dreaptă"],"correctIndices":[1],"correct":1,"explanation":"Atunci când doriți să intrați într-o intersecție și întâlniți indicatorul “Cedează trecerea”, aveți obligația de a reduce viteza de deplasare, vă asigurați că pe drumul prioritar nu circulă alte vehicule, și abia apoi puteți să pătrundeți în intersecție, iar dacă pe drumul transversal circulă în acel moment alte vehicule, opriți pentru a le acorda prioritate de trecere, după care vă puteți continua deplasarea.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1088.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1088.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1088; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1087 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-veti-proceda-pentru-a-traversa-intersectia-daca-intalniti-indicatorul-cedeaza-trecerea","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1087","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1089","batch":"22","category":"Categoria B","question":"Cum procedați la întâlnirea unui obstacol pe sensul dumneavoastră de mers, în situația în care pentru a-l depăși intrați pe contrasens, iar din față se apropie alt vehicul:","answers":["Reduceți viteza și, la nevoie, opriți","Opriți și înlăturați obstacolul","Opriți și așteptați echipajul de intervenție"],"correctIndices":[0],"correct":0,"explanation":"Atunci când pe sensul dumneavoastră de mers întâlniți un obstacol și pentru a-l depăși trebuie să intrați pe contrasens, iar din față se apropie alt vehicul, trebuie să reduceți viteza de deplasarea și la nevoie să opriți pentru a aștepta trecerea vehiculului care circulă din sens opus, după care puteți depăși obstacolul.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1089.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1089.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1089; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1088 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-procedati-la-intalnirea-unui-obstacol-pe-sensul-dumneavoastra-de-mers-in-situatia-in-care-pentru-a-l-depasi-intrati-pe-contrasens-iar-di","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1088","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1090","batch":"22","category":"Categoria B","question":"Interzicerea trecerii la nivel cu calea ferată curentă, prevăzută cu instalații de semnalizare automată fără bariere, se realizează prin:","answers":["Dispozitivele cu lumini intermitent-alternative roșii și stingerea semnalizării reprezentată de lumina intermitent albă","Semnalele luminoase intermitente de culoare albă","Dispozitivele optice cu lumini alternative roșii și albe"],"correctIndices":[0],"correct":0,"explanation":"La trecerea la nivel cu calea ferată curentă prevăzută cu instalație de semnalizare automată fără bariere, interzicerea circulației rutiere se realizează optic, prin stingerea semnalizării de control reprezentată de lumina intermitentă albă și aprinderea luminilor intermitent-alternative roșii, iar acustic, prin emiterea de semnale sonore intermitente.Pentru a putea traversa calea ferată trebuie să așteptați stingerea luminilor de culoare roșie și a semnalului sonor, iar după apariția semnalului intermitent cu lumină de culoare albă cu cadență lentă, vă puteți continua deplasarea.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1090.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1090.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1090; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1089 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/interzicerea-trecerii-la-nivel-cu-calea-ferata-curenta-prevazuta-cu-instalatii-de-semnalizare-automata-fara-bariere-se-realizeaza-prin","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1089","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1091","batch":"22","category":"Categoria B","question":"Puteți efectua depășirea camionului?","answers":["Nu, deoarece nu aveți vizibilitate suficientă","Da, deoarece interzicerea depășirii se referă numai la autovehiculele destinate transportului de marfă","Nu, deoarece indicatorul interzice depășirea autovehiculelor"],"correctIndices":[1],"correct":1,"explanation":"Manevra de depășire este interzisă în locurile cu vizibilitate sub 50 de metri, dar în situația din imagine vizibilitatea este bună, peste 50 de metri. În această situație intenționați să depășiți autocamionul din fața dvs. și întâlniți indicatorul „Depășirea interzisă autovehiculelor destinate transportului de mărfuri”. Acest indicator interzice conducătorilor de autovehicule de transport marfă să efectueze manevra de depășire a autovehiculelor, excepție făcând motocicletele fără ataș și mopedele, care pot fi depășite. Având în vedere că dvs. conduceți un autovehicul din categoria B indicatorul nu vi se adresează și vă puteți continua manevra de depășire a autocamionului. Indicatorul „Depășirea interzisă autovehiculelor destinate transportului de mărfuri” nu vi se adresează. Vedeți explicația de la varianta B de răspuns.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1091.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1091.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1091; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Perspectiva unui șofer asupra unui drum cu două benzi. În fața lui se află un camion. Este prezent indicatorul circular cu simbolurile unui camion roșu și al unui autoturism negru, ce semnifică 'Depășirea interzisă pentru camioane'. Șoferul intenționează să depășească camionul. Nu vine trafic de pe contrasens.","needsImageReview":true,"source":"RoDrive · ID 1090 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/puteti-efectua-depasirea-camionului","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1090","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1120.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1092","batch":"22","category":"Categoria B","question":"Este interzisă staționarea în dreptul marcajului longitudinal continuu, aplicat între sensurile de circulație?","answers":["Nu","Da, atunci când conducătorii celorlalte vehicule ar fi obligați astfel să treacă peste marcajul respectiv","Legal, nu este prevăzut"],"correctIndices":[1],"correct":1,"explanation":"Se interzice staționarea voluntară a vehiculelor în toate cazurile în care este interzisă oprirea voluntară, iar oprirea voluntară este interzisă în dreptul marcajului continuu, atunci când conducătorii celorlalte vehicule care circulă în același sens sunt obligați din această cauză să încalce marcajul continuu. Astfel, în aceste locuri este interzisă și manevra de staționare voluntară a vehiculelor.Dar în situația în care prin staționare nu îi obligă pe conducătorii celorlalte vehicule care circulă în același sens să încalce marcajul continuu de separare a sensurilor de circulație, manevra de staționare este regulamentară, ca de exemplu pe un drum foarte lat sau pe un drum cu două sau mai multe benzi de circulație pe sens, unde, prin manevra de staționare, ceilalți conducători de vehicule nu sunt obligați din această cauză sa încalce marcajul continuu.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1092.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1092.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1092; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1091 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/este-interzisa-stationarea-in-dreptul-marcajului-longitudinal-continuu-aplicat-intre-sensurile-de-circulatie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1091","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1093","batch":"22","category":"Categoria B","question":"Când se poate face radierea din evidență a unui vehicul, la cererea proprietarului?","answers":["La schimbarea oricăror date referitoare la identificarea vehiculului respectiv","La schimbarea domiciliului ori a sediului unității deținătoare","Când proprietarul face dovada dezmembrării, casării sau predării vehiculului la unități specializate, în vederea dezmembrării"],"correctIndices":[2],"correct":2,"explanation":"Radierea din evidență a vehiculelor se face de către autoritatea care a efectuat înmatricularea sau înregistrarea, la cererea proprietarului, în anumite condiții, printre care și atunci când acesta face dovada dezmembrării, casării sau predării vehiculului la unități specializate în vederea dezmembrării, situație în care radierea este definitivă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1093.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1093.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1093; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1092 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cand-se-poate-face-radierea-din-evidenta-a-unui-vehicul-la-cererea-proprietarului","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1092","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1094","batch":"22","category":"Categoria B","question":"Ce informație oferă indicatorul?","answers":["Indică un traseu de drum deschis traficului internațional","Interzice accesul autoturismelor în oraș și indică traseul de urmat pentru ocolirea acestuia","Indică traseul de ocolire a localității"],"correctIndices":[2],"correct":2,"explanation":"Indicatorul din imagine se numește “Presemnalizarea traseului de evitare a localității”. Conducătorul auto va întâlni acest indicator la 100-200 metri de intersecția cu drumul de ocolire a localității, indicatorul marcând ruta ce permite evitarea localității. Pe indicator mai pot fi scrise și alte trasee, spre alte localități importante.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1094.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1094.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1094; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Panoul albastru indică direcțiile către Constanța (E60) și Slobozia. Pe lânga forma localității Slobozia este o săgeată care se bifurcă, primul capăt trecând prin Slobozia și al doilea, care înconjoară partea din dreapta și se termină în partea de sus a localității, pentru a sugera un alt traseu, de ocolire.","needsImageReview":true,"source":"RoDrive · ID 1093 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-informatie-ofera-indicatorul","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1093","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1123.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1095","batch":"22","category":"Categoria B","question":"Mersul înapoi este interzis:","answers":["Pe o distanță mai mare de 50 m","Legal, nu este prevăzută o anumită distanță","Pe o distanță mai mare de 100 m"],"correctIndices":[0],"correct":0,"explanation":"Legislația rutieră interzice conducătorilor de vehicule să efectueze manevra de mers înapoi pe o distanță mai mare de 50 de metri. Pe orice tip sau categorie de drum circulați, dacă mersul înapoi cu vehiculul este permis, tot pe o distanță de maxim 50 de metri puteți manevra vehiculul înapoi.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1095.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1095.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1095; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1094 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/mersul-inapoi-este-interzis","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1094","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1096","batch":"22","category":"Categoria B","question":"Cum veți proceda corect dacă, aflându-vă în interiorul unei intersecții cu circulație în sens giratoriu, observați că pe un drum lateral circulă o coloană cu regim de circulație prioritară?","answers":["Vă continuați drumul, deoarece aveți prioritate de trecere în sensul giratoriu","Opriți și acordați prioritate coloanei cu regim prioritar","Virați la dreapta și părăsiți intersecția"],"correctIndices":[1],"correct":1,"explanation":"Coloana cu regim prioritarva avea întotdeauna în funcțiune semnale speciale de avertizare sonore și luminoase de culoare roșie, acestea obligă participanții la trafic să oprească în direcția de mers cât mai aproape de marginea drumului, iar atunci când este întâlnită în intersecții, participanții la trafic au obligația să îi acorde prioritate de trecere. Prin urmare, atunci când întâlniți o coloană cu regim de circulație prioritar, chiar dacă traversați o intersecție dirijată, nedirijată sau cu sens giratoriu, chiar dacă acea coloană cu regim prioritar vine de pe un drum prioritar sau nu, aveți obligația de a opri și de a acorda prioritate de trecere coloanei cu regim de circulație prioritar.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1096.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1096.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1096; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1095 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-veti-proceda-corect-daca-aflandu-va-in-interiorul-unei-intersectii-cu-circulatie-in-sens-giratoriu-observati-ca-pe-un-drum-lateral-circu","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1095","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1097","batch":"22","category":"Categoria B","question":"Este permisă depășirea când din sens opus se apropie, la mică distanță, alt vehicul?","answers":["Da, dacă prin depășire se trece peste axa drumului","Da, dacă drumul are o lățime suficientă, iar prin depășire nu se trece peste axa drumului","Da, dacă nu există interdicția de a depăși"],"correctIndices":[1],"correct":1,"explanation":"Atunci când din sens opus se apropie un alt vehicul, depășirea nu poate fi efectuată dacă se trece peste axa care separă sensurile de circulaţie. Prin urmare, această variantă nu poate fi corectă. Atunci când din sens opus se apropie la mică distanță un alt vehicul, vă este permsiă manevra de depășire doar dacă drumul are o lățime suficientă iar prin efectuarea manevrei de depășire nu se trece peste axa drumului. Chiar dacă nu exista interdicția de a depăși, această manevră nu se poate efectua dacă din sens opus se apropie un alt vehicul, cu excepția cazului în care pentru afectuarea manevrei NU se trece peste axa care separă sensurile de circulaţie. Prin urmare, această variantă nu poate fi corectă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1097.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1097.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1097; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1096 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/este-permisa-depasirea-cand-din-sens-opus-se-apropie-la-mica-distanta-alt-vehicul","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1096","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1098","batch":"22","category":"Categoria B","question":"Brațul stâng, întins orizontal, al unui biciclist semnifică:","answers":["Intenția de a schimba direcția de mers la stânga sau de a depăși","Intenția de a opri","Faptul că nu trebuie să fie depășit"],"correctIndices":[0],"correct":0,"explanation":"Semnalul efectuat de către conducătorul de bicicletă prin ridicarea brațului stâng are două semnificații. Acesta poate semnifica intenția biciclistului de a schimba direcția de mers către stânga, sau poate semnifica intenția biciclistului de a depăși.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1098.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1098.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1098; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1097 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/bratul-stang-intins-orizontal-al-unui-biciclist-semnifica","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1097","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1099","batch":"22","category":"Categoria B","question":"Ce semnifică indicatorul din imagine?","answers":["Zonă în care viteza recomandată este de 30 km/h","Zonă în care este interzisă circulația sub 30 km/h","Zonă în care le este interzis autovehiculelor destinate transportului de mărfuri să circule cu peste 30 km/h"],"correctIndices":[0],"correct":0,"explanation":"Indicatorul se numește “Zonă cu viteza recomandată 30 km/h”, acest indicator se găsește instalat în zonele urbane în care viteza înscrisă pe indicator, adică viteza de 30 de km/h în această situație, este considerată ca fiind viteza potrivită pentru a circula în condiții de siguranță.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1099.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1099.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1099; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Indicatorul pătrat albastru cu inscripția 'ZONA 30' semnifică o zonă cu recomandare de viteză la 30 km/h.","needsImageReview":true,"source":"RoDrive · ID 1098 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-semnifica-indicatorul-din-imagine","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1098","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1129.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1100","batch":"22","category":"Categoria B","question":"În acest sens giratoriu, sunteți încadrat corespunzător pentru:","answers":["A vira la dreapta","A vira la stânga sau pentru a circula înainte","A circula înainte"],"correctIndices":[1],"correct":1,"explanation":"În această situație intenționați sa traversați o intersecție cu circulație în sens giratoriu și v-ați încadrat pe banda a doua, de pe aceasta bandă puteți circula pe direcția înainte, puteți vira către stânga sau puteți întoarce autovehiculul. Din aceasta poziție nu puteți efectua virajul către dreapta. În cazul în care v-ați fi încadrat pe prima bandă, ați fi putut circula pe direcția înainte sau să virați către dreapta. Deci în această situație v-ați încadrat corect pentru a vira catre stânga sau pentru a circula pe direcția înainte.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1100.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1100.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1100; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție semnalizată cu indicatorul 'Sens giratoriu' (circular albastru cu săgeți albe ce formează un cerc) și un semafor verde. Șoferul vrea să intre în sensul giratoriu. Indicatorul adițional semnalizează direcția către 'Aeroport'. Șoferul este încadrat pe banda din stânga, ce îi permite să intre în giratoriu pe banda din interiorul sensului giratoriu.","needsImageReview":true,"source":"RoDrive · ID 1099 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-acest-sens-giratoriu-sunteti-incadrat-corespunzator-pentru","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1099","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1130.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"}]);})();
